# -*- coding: utf-8 -*-
import json
import random

with open('scripts/half_q.json', 'r', encoding='utf-8') as f:
    items = json.load(f)

print(f"Loaded existing items: {len(items)}")

def add(q, a, w, cat, exp):
    opts = [a] + list(w)
    random.shuffle(opts)
    items.append({
        "id": f"t500-{len(items)+1}",
        "gameId": "trivia_spark",
        "category": cat,
        "question": q,
        "options": opts,
        "correctAnswer": a,
        "explanation": exp
    })

