# Check integrity of all items:
for idx, q in enumerate(items):
    assert len(q["options"]) == 4, f"Question {idx+1} does not have 4 options"
    assert q["correctAnswer"] in q["options"], f"Question {idx+1} correct answer not in options"
    assert len(q["question"]) > 5, f"Question {idx+1} question text too short"
    assert len(q["explanation"]) > 5, f"Question {idx+1} explanation too short"

print("All 500 questions passed validation successfully!")

# Write to src/data/trivia500Bank.ts
ts_content = """import { QuestionItem } from '../types/game';

// بنك الـ 500 سؤال الشامل والمعتمد للعبة أسئلة ونقاط (JAMR Trivia Spark)
// تم إعدادها وتدقيقها بدقة لتشمل كافة المجالات بدون تكرار
export const TRIVIA_500_BANK: QuestionItem[] = """ + json.dumps(items, ensure_ascii=False, indent=2) + ";\n"

with open('src/data/trivia500Bank.ts', 'w', encoding='utf-8') as f:
    f.write(ts_content)

print("Saved src/data/trivia500Bank.ts successfully!")
